def transform(grid):
    g = np.array(grid)
    bg = background(g)
    best = None
    for o in objects(g, bg=bg):
        y0, x0, y1, x1 = o["box"]
        if y1 - y0 < 2 or x1 - x0 < 2:
            continue
        border = 2 * (y1 - y0 + 1) + 2 * (x1 - x0 + 1) - 4
        cs = set(o["cells"])
        if len(cs) == border and all(y in (y0, y1) or x in (x0, x1) for y, x in cs):
            if best is None or o["size"] > best["size"]:
                best = o
    fy0, fx0, fy1, fx1 = best["box"]
    iy0, ix0, iy1, ix1 = fy0 + 1, fx0 + 1, fy1 - 1, fx1 - 1
    out = g[iy0:iy1 + 1, ix0:ix1 + 1].copy()
    emit(out, "Crop the interior of the frame: this window is the output canvas.")

    mask = g != bg
    mask[fy0:fy1 + 1, fx0:fx1 + 1] = False
    groups = {}
    for comp in components(mask, diagonal=False):
        key = frozenset(int(g[y, x]) for y, x in comp)
        groups.setdefault(key, []).extend(comp)

    def inwin(y, x):
        return iy0 <= y <= iy1 and ix0 <= x <= ix1

    for key, cells in groups.items():
        y0, x0, y1, x1 = bbox(cells)
        if y1 < iy0 or y0 > iy1 or x1 < ix0 or x0 > ix1:
            continue
        cols = sorted(key)
        par = {}
        for y, x in cells:
            parity = (y + x) % 2
            c = int(g[y, x])
            if parity in par and par[parity] != c:
                raise ValueError('Visible outline has inconsistent alternation')
            par[parity] = c

        def colour_at(y, x):
            if len(cols) == 1:
                return cols[0]
            return par[(y + x) % 2]

        drew = False
        for y in range(y0, y1 + 1):
            for x in range(x0, x1 + 1):
                if not (y in (y0, y1) or x in (x0, x1)):
                    continue
                if inwin(y, x):
                    out[y - iy0, x - ix0] = colour_at(y, x)
                    drew = True
        if drew:
            emit(out, f"Complete the hidden part of the rectangle outline of colours {cols} inside the window.")
    emit(out, "Final: the window showing the completed hidden outlines.")
    return out
